// Bundled Lattice Design System fonts (decision: exact design match, offline,
// MV3-safe). The font binaries are embedded as base64 woff2 and registered with the
// document font set via the FontFace API — NOT as @font-face in the shadow root,
// because Chrome ignores @font-face declared inside a shadow tree. Registering on
// document.fonts (which shadow DOM inherits) and sourcing from an ArrayBuffer also
// sidesteps any host-page CSP font-src restriction on data: URIs.
//
//   --sk-font-ui:  Urbanist          (UI / titles / body — 400/500/600/700)
//   --sk-font-label: IBM Plex Mono   (overlines & section labels — 500)
//
// Variable woff2, latin subset, from Google Fonts (all OFL).

interface FontFaceDef {
  family: string;
  /** Variable-font weight range for the FontFace descriptor. */
  weight: string;
  /** base64-encoded woff2 binary. */
  data: string;
}

const FONT_FACES: FontFaceDef[] = [
  { family: "Urbanist", weight: "400 700", data:
    "" },
  { family: "IBM Plex Mono", weight: "500", data:
    "" },
];

function decode(b64: string): ArrayBuffer {
  const bin = atob(b64);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return buf.buffer;
}

let loaded = false;

/**
 * Register the bundled typefaces with the document font set, once per document.
 * Idempotent and safe to call on every mount. A no-op where the FontFace API is
 * absent (e.g. the jsdom/happy-dom test environment).
 */
export function ensureFontsLoaded(): void {
  if (loaded) return;
  const FF = (globalThis as { FontFace?: typeof FontFace }).FontFace;
  const fontSet = (document as Document & { fonts?: FontFaceSet }).fonts;
  if (!FF || !fontSet) return;
  loaded = true;
  for (const f of FONT_FACES) {
    try {
      const face = new FF(f.family, decode(f.data), {
        weight: f.weight,
        style: "normal",
        display: "swap",
      });
      fontSet.add(face);
      void face.load();
    } catch {
      // A single bad face must not block the others or the UI.
    }
  }
}
